import { Vec3 } from "std/vector"
import * as array from "std/array"
import * as spatial from "../spatial"

// Exact nearest points in the x/z plane. Caller indices break equal-distance
// ties. Keep this immutable index with its source positions and rebuild when
// membership or positions change; counts and other payloads do not matter.
const build = fn (points: Array Vec3) => do:
  for point in points:
    if Bool.not (is_finite point.x && is_finite point.z):
      return @panic "point index requires finite coordinates"
  return spatial.build (array.map (fn p => do:
    let point = #Vec3 { x: p.x, y: 0.0, z: p.z }
    return #spatial.Bounds { low: point, high: point }) points)

const distance = distance_offset 0.0
const distance_offset = fn (vertical_squared: F32) (bounds: Array F32) (node: U32) (at: Vec3) => do:
  let offset = node * 6
  let x = max 0.0 (max (bounds[offset] - at.x) (at.x - bounds[offset + 3]))
  let z = max 0.0 (max (bounds[offset + 2] - at.z) (at.z - bounds[offset + 5]))
  return (x * x + vertical_squared) + z * z

const nearest = fn index at => nearest_where (fn id => #True) index at
const nearest_where = nearest_where_offset 0.0
// Preserve the caller's squared-distance rounding to a common horizontal plane.
const nearest_where_offset = fn (vertical_squared: F32) eligible (index: spatial.Index) (at: Vec3) => do:
  if index.order.length == 0 || Bool.not (is_finite at.x && is_finite at.z):
    return #Nothing
  let stack = array.fill 64 0
  stack[0] := 1
  let top = 1
  let best = 4294967295
  let closest = (1.0 / 0.0)
  for 0 .. index.base * 2:
    if top == 0:
      break
    top := self - 1
    let node = stack[top]
    let apart = distance_offset vertical_squared index.bounds node at
    if apart <= closest:
      if node >= index.base:
        let leaf = node - index.base
        if leaf < index.order.length:
          let id = index.order[leaf]
          if eligible id && (apart < closest || (apart == closest && id < best)):
            best := id
            closest := apart
      else:
        let a = node * 2
        let b = a + 1
        let first = if distance_offset vertical_squared index.bounds a at <= distance_offset vertical_squared index.bounds b at then a else b
        stack[top] := if first == a then b else a
        stack[top + 1] := first
        top := self + 2
  return if best == 4294967295 then #Nothing else #Some best

sources.lib/scene.blot:
import * as changes from "./changes"
import * as array from "std/array"
import { Vec3 } from "std/vector"
import { Quat, Vec4 } from "./math"
import * as math from "./math"
import * as shapes from "./shapes"
import * as terrain from "./terrain"
import * as spatial from "./spatial"
import { Shape } from "./shapes"

// What physics sees of a world: every entity with a collider, a body, a
// character or a brush becomes a proxy with a world-space shape and bounds.
// Callers build `Source` values from their own data. Queries (ray, shape cast,
// overlap) run against the scene built from those sources.

type ShapeKind is data = #Box | #Sphere | #Capsule | #Brush | #Heightfield terrain.Terrain
type BodyKind is data = #Dynamic | #Kinematic | #Static

// A collider as authored on an entity.
type Collider is data = #Collider {
  shape: ShapeKind,
  size: Vec3,
  radius: F32,
  height: F32,
  offset: Vec3,
  friction: F32,
  restitution: F32,
  layer: U32,
  mask: U32,
  trigger: Bool,
}

// A rigid body as authored, plus its simulation state.
type Rigid is data = #Rigid {
  kind: BodyKind,
  mass: F32,
  gravity_scale: F32,
  linear_damping: F32,
  angular_damping: F32,
  can_sleep: Bool,
  continuous: Bool,
  linear_velocity: Vec3,
  angular_velocity: Vec3,
  sleeping: Bool,
  sleep_time: F32,
}

// A character controller as authored, plus its state.
type Walker is data = #Walker {
  max_slope: F32,
  step_height: F32,
  snap_distance: F32,
  push: F32,
  velocity: Vec3,
  grounded: Bool,
  ground: U32,
  ground_normal: Vec3,
}

// One entity as physics reads it. Pose is in world space.
type Source is data = #Source {
  index: U32,
  id: U32,
  position: Vec3,
  rotation: Quat,
  scale: Vec3,
  collider: Maybe Collider,
  rigid: Maybe Rigid,
  walker: Maybe Walker,
  planes: Array Vec4,
}

// Proxy kinds.
const kind_static: U32 = 0
const kind_kinematic: U32 = 1
const kind_dynamic: U32 = 2

type Proxy is data = #Proxy {
  source: U32,
  id: U32,
  kind: U32,
  walker: Bool,
  shape: Shape,
  inertia: Vec3,
  inscribed: F32,
  low: Vec3,
  high: Vec3,
  layer: U32,
  mask: U32,
  friction: F32,
  restitution: F32,
  trigger: Bool,
}

type Scene is data = #Scene { proxies: Array Proxy, index: spatial.Index, slots: Array U32, source_count: U32 }

// The proxy moved by `shift` (translation only).
const shifted = fn (proxy: Proxy) => fn (shift: Vec3) => do:
  let shape = case proxy.shape of
    #shapes.Capsule { a, b, radius } => #shapes.Capsule { a: a + shift, b: b + shift, radius }
    #shapes.Hull poly => #shapes.Hull (shapes.poly_place poly shift math.identity_quat math.one3)
    #shapes.Heightfield t => do:
      t.origin := self + shift
      break #shapes.Heightfield t
  proxy.shape := shape
  proxy.low := self + shift
  proxy.high := self + shift
  return proxy

// A cast hit: the entity, the fraction of the motion travelled before
// touching, the contact point and normal (from the shape toward the moving
// capsule), and how deep the capsule started inside if it did.
type Hit is data = #Hit { id: U32, proxy: U32, time: F32, distance: F32, point: Vec3, normal: Vec3, surface: Vec3, depth: F32 }

const default_collider = #Collider {
  shape: #Brush,
  size: math.one3,
  radius: 0.5,
  height: 2.0,
  offset: math.zero3,
  friction: 0.6,
  restitution: 0.0,
  layer: 1,
  mask: 65535,
  trigger: #False,
}

const default_rigid = #Rigid {
  kind: #Dynamic, mass: 1.0, gravity_scale: 1.0,
  linear_damping: 0.0, angular_damping: 0.05,
  can_sleep: #True, continuous: #True,
  linear_velocity: math.zero3, angular_velocity: math.zero3,
  sleeping: #False, sleep_time: 0.0,
}
const default_walker = #Walker {
  max_slope: 50.0, step_height: 0.4, snap_distance: 0.3, push: 1.0,
  velocity: math.zero3, grounded: #False, ground: 0, ground_normal: math.up,
}

const source = fn (id: U32) => fn (position: Vec3) => #Source {
  index: 0, id, position, rotation: math.identity_quat, scale: math.one3,
  collider: #Nothing, rigid: #Nothing, walker: #Nothing, planes: #[],
}

// The default collider with a shape and its dimensions, and a source holding
// one, each made at once: every field update copies the whole record.
const shaped = fn (shape: ShapeKind) => fn (size: Vec3) => fn (radius: F32) => fn (height: F32) => fn (offset: Vec3) => do:
  let d = default_collider
  return #Collider { shape, size, radius, height, offset, friction: d.friction, restitution: d.restitution, layer: d.layer, mask: d.mask, trigger: d.trigger }

const holding = fn (id: U32) => fn (position: Vec3) => fn (collider: Collider) => fn (walker: Maybe Walker) => #Source {
  index: 0, id, position, rotation: math.identity_quat, scale: math.one3,
  collider: #Some collider, rigid: #Nothing, walker, planes: #[],
}

const box = fn (id: U32) => fn (position: Vec3) => fn (size: Vec3) => do:
  let d = default_collider
  return holding id position (shaped #Box size d.radius d.height d.offset) #Nothing

const sphere = fn (id: U32) => fn (position: Vec3) => fn (radius: F32) => do:
  let d = default_collider
  return holding id position (shaped #Sphere d.size radius d.height d.offset) #Nothing

const capsule = fn (id: U32) => fn (position: Vec3) => fn (radius: F32) => fn (height: F32) => do:
  let d = default_collider
  return holding id position (shaped #Capsule d.size radius height d.offset) #Nothing

const dynamic = fn (s: Source) => do:
  s.rigid := #Some default_rigid
  return s

// Characters are positioned by their feet.
const character = fn (id: U32) => fn (position: Vec3) => do:
  let d = default_collider
  return holding id position (shaped #Capsule d.size 0.4 1.8 (math.vec3 0.0 0.9 0.0)) (#Some default_walker)

// Finite terrain is authored in world space and remains immovable.
const ground = fn (id: U32) => fn (t: terrain.Terrain) => do:
  let d = default_collider
  return holding id t.origin (shaped (#Heightfield t) d.size d.radius d.height d.offset) #Nothing

// Compose a local pose with a parent pose.
const rotate = fn (q: Quat) => fn (v: Vec3) => math.Quat.rotate q v
const compose = fn (a: Quat) => fn (b: Quat) => a * b
const scale_by = fn (a: Vec3) => fn (b: Vec3) => shapes.mul3 a b

// The world-space shape of a source, its principal inertia per unit mass and
// the radius of the largest sphere inside it; or nothing if it has no shape.
// Pose arithmetic stays scalar, in Vec3 operation order: each Vec3 temporary
// costs a heap allocation.
const shape_of = fn (source: Source) => fn (collider: Collider) => do:
  let sx = abs source.scale.x
  let sy = abs source.scale.y
  let sz = abs source.scale.z
  let q = source.rotation
  let (ox, oy, oz) = math.rotate_parts q.x q.y q.z q.w (collider.offset.x * source.scale.x) (collider.offset.y * source.scale.y) (collider.offset.z * source.scale.z)
  let p = source.position
  let center = #Vec3 { x: p.x + ox, y: p.y + oy, z: p.z + oz }
  return case collider.shape of
    #Heightfield t => #Some (#shapes.Heightfield t, math.zero3, 0.0)
    #Box => do:
      let half = #Vec3 { x: collider.size.x * sx * 0.5, y: collider.size.y * sy * 0.5, z: collider.size.z * sz * 0.5 }
      let poly = shapes.box_poly center q half
      break #Some (#shapes.Hull poly, shapes.box_inertia half, min half.x (min half.y half.z))
    #Sphere => do:
      let radius = collider.radius * max sx (max sy sz)
      let i = shapes.sphere_inertia radius
      break #Some (#shapes.Capsule { a: center, b: center, radius }, #Vec3 { x: i, y: i, z: i }, radius)
    #Capsule => do:
      let radius = collider.radius * max sx sz
      let half_segment = max 0.0 (collider.height * sy * 0.5 - radius)
      let (ux, uy, uz) = math.rotate_parts q.x q.y q.z q.w 0.0 1.0 0.0
      let ax = ux * half_segment
      let ay = uy * half_segment
      let az = uz * half_segment
      let a = #Vec3 { x: center.x - ax, y: center.y - ay, z: center.z - az }
      let b = #Vec3 { x: center.x + ax, y: center.y + ay, z: center.z + az }
      break #Some (#shapes.Capsule { a, b, radius }, shapes.capsule_inertia radius half_segment, radius)
    #Brush => do:
      let #Some local = shapes.hull_poly source.planes else:
        break #Nothing
      let (low, high) = shapes.bounds (#shapes.Hull local)
      let half = #Vec3 { x: (high.x - low.x) * sx * 0.5, y: (high.y - low.y) * sy * 0.5, z: (high.z - low.z) * sz * 0.5 }
      let poly = shapes.poly_place local source.position q source.scale
      break #Some (#shapes.Hull poly, shapes.box_inertia half, min half.x (min half.y half.z))

const kind_of = fn (source: Source) => case source.rigid of
  #Some r => case r.kind of
    #Dynamic => kind_dynamic
    #Kinematic => kind_kinematic
    #Static => kind_static
  #Nothing => case source.walker of
    #Some _ => kind_kinematic
    #Nothing => kind_static

const proxy_of = fn (index: U32) => fn (source: Source) => do:
  let collider = case source.collider of
    #Some c => c
    #Nothing => default_collider
  if source.planes.is_empty:
    let #Some _ = source.collider else:
      return #Nothing
  let kind = kind_of source
  if let #Heightfield _ = collider.shape:
    kind := kind_static
  let is_walker = case source.walker of
    #Some _ => #True
    #Nothing => #False
  // A dynamic body turns about its origin: it has no collider offset. A
  // character is as big as its capsule says and always stands upright,
  // whatever its transform's scale and rotation (a first-person camera
  // turns the transform).
  if kind == kind_dynamic:
    collider.offset := math.zero3
  if is_walker:
    source.scale := math.one3
    source.rotation := math.identity_quat
  let #Some (shape, inertia, inscribed) = shape_of source collider else:
    return #Nothing
  // A capsule's bounds as shapes.bounds makes them, without temporaries.
  let (low, high) = case shape of
    #shapes.Capsule { a, b, radius } => (#Vec3 { x: min a.x b.x - radius, y: min a.y b.y - radius, z: min a.z b.z - radius }, #Vec3 { x: max a.x b.x + radius, y: max a.y b.y + radius, z: max a.z b.z + radius })
    _ => shapes.bounds shape
  return #Some (#Proxy {
    source: index,
    id: source.id,
    kind,
    walker: is_walker,
    shape,
    inertia,
    inscribed,
    low,
    high,
    layer: collider.layer,
    mask: collider.mask,
    friction: collider.friction,
    restitution: collider.restitution,
    trigger: collider.trigger,
  })

// Proxies for every source that has a shape, in source order. Boxed proxies
// fill exactly sized arrays: appending them to a List one at a time is
// quadratic on the pinned compiler.
const build = fn (sources: Array Source) => do:
  let n = sources.length
  let candidates = @array.generate n (fn (i: U32) => proxy_of i sources[i])
  let count = 0
  for candidate in candidates:
    if let #Some _ = candidate:
      count := self + 1
  let slots = @array.fill n count
  let owners = @array.fill count 0
  let next = 0
  for i in 0..n:
    if let #Some _ = candidates[i]:
      slots[i] := next
      owners[next] := i
      next := self + 1
  let proxies = @array.generate count (fn (k: U32) => case candidates[owners[k]] of
    #Some proxy => proxy
    #Nothing => @panic "scene proxy owner has no shape")
  let index = spatial.build (@array.generate count (fn (i: U32) => #spatial.Bounds { low: proxies[i].low, high: proxies[i].high }))
  return #Scene { proxies, index, slots, source_count: n }

// Explicit dirty source indices avoid inspecting/rebuilding unchanged geometry.
// Source order/count or shape presence changes rebuild the tree as needed.
const update = fn (sources: Array Source) => fn (previous: Scene) => fn (changed: Array U32) => do:
  if sources.length != previous.source_count:
    return build sources
  if changed.is_empty:
    return previous
  let n = sources.length
  let count = previous.proxies.length
  // Each changed slot's proxy is made once. Slot `count` stands for a source
  // out of range or without a proxy, which refit skips. Exactly sized arrays
  // and no early exit keep the proxy copy's writes in place.
  let next = @array.generate changed.length (fn (k: U32) => do:
    let source = changed[k]
    if source < n:
      return proxy_of source sources[source]
    return #Nothing)
  let dirty = @array.generate changed.length (fn (k: U32) => do:
    let source = changed[k]
    if source < n:
      return previous.slots[source]
    return count)
  let rebuild = #False
  for k in 0..changed.length:
    if let #Some _ = next[k]:
      if dirty[k] >= count:
        rebuild := #True
    else:
      if dirty[k] < count:
        rebuild := #True
  if rebuild:
    return build sources
  let proxies = @array.generate count (fn (i: U32) => previous.proxies[i])
  for k in 0..changed.length:
    if let #Some p = next[k]:
      proxies[dirty[k]] := p
  let bounds = @array.generate changed.length (fn (k: U32) => case next[k] of
    #Some p => #spatial.Bounds { low: p.low, high: p.high }
    #Nothing => #spatial.Bounds { low: math.zero3, high: math.zero3 })
  let index = spatial.refit previous.index dirty bounds
  return #Scene { proxies, index, slots: previous.slots, source_count: n }

// Queries ---------------------------------------------------------------------------

// Do the bounds [low, high] (grown by `grow`) overlap the proxy's?
const touches_bounds = fn (proxy: Proxy) => fn (low: Vec3) => fn (high: Vec3) =>
  low.x <= proxy.high.x && high.x >= proxy.low.x && low.y <= proxy.high.y && high.y >= proxy.low.y && low.z <= proxy.high.z && high.z >= proxy.low.z

const hit_eps = 0.0003

// Move a capsule (segment ab, radius) by `delta` against one shape. Returns
// the first contact along the way: the fraction of `delta` travelled, the
// contact point on the shape, the normal pointing from the shape to the
// capsule, and how deep the capsule already was. If it overlaps at the start
// the fraction is 0.
const cast_shape = fn (shape: Shape) => fn (a: Vec3) => fn (b: Vec3) => fn (radius: F32) => fn (delta: Vec3) => do:
  let t = 0.0
  let heightfield = #False
  if let #shapes.Heightfield _ = shape:
    heightfield := #True
  let steps = 40
  if heightfield:
    steps := 96
  for 0..steps:
    let gap = shapes.segment_gap shape (#Vec3 { x: a.x + delta.x * t, y: a.y + delta.y * t, z: a.z + delta.z * t }) (#Vec3 { x: b.x + delta.x * t, y: b.y + delta.y * t, z: b.z + delta.z * t })
    let clearance = gap.dist - radius
    if clearance <= hit_eps:
      return #Some (t, gap.on_shape, gap.normal, gap.surface, if t == 0.0 then max 0.0 (F32.neg clearance) else 0.0)
    let closing = F32.neg (gap.normal.dot delta)
    if heightfield:
      closing := delta.length
    if closing <= 0.000001:
      return #Nothing
    t := self + clearance / closing
    if t > 1.0:
      return #Nothing
  return #Nothing

// Bounds swept by a moving capsule: the corners' least and greatest
// coordinates, before and after the move, widened by the radius. Scalars keep
// the Vec3 operation order without allocating temporaries.
const swept_bounds = fn (a: Vec3) => fn (b: Vec3) => fn (radius: F32) => fn (delta: Vec3) => do:
  let ex = a.x + delta.x
  let ey = a.y + delta.y
  let ez = a.z + delta.z
  let fx = b.x + delta.x
  let fy = b.y + delta.y
  let fz = b.z + delta.z
  let low = #Vec3 { x: min (min a.x b.x) (min ex fx) - radius, y: min (min a.y b.y) (min ey fy) - radius, z: min (min a.z b.z) (min ez fz) - radius }
  let high = #Vec3 { x: max (max a.x b.x) (max ex fx) + radius, y: max (max a.y b.y) (max ey fy) + radius, z: max (max a.z b.z) (max ez fz) + radius }
  return (low, high)

// What a cast can touch: proxies on `mask` layers, never `skip` (an entity id),
// triggers only if `triggers`, characters only if `walkers`, dynamic bodies
// only if `dynamics`.
type Filter is data = #Filter { mask: U32, skip: U32, triggers: Bool, walkers: Bool, dynamics: Bool }

const accepts = fn (f: Filter) => fn (proxy: Proxy) =>
  (proxy.layer & f.mask) != 0 && proxy.id != f.skip && (f.triggers || Bool.not proxy.trigger) && (f.walkers || Bool.not proxy.walker) && (f.dynamics || proxy.kind != kind_dynamic)

// The nearest hit of a moving capsule, if any.
const cast = fn (scene: Scene) => fn (a: Vec3) => fn (b: Vec3) => fn (radius: F32) => fn (delta: Vec3) => fn (filter: Filter) => do:
  let (low, high) = swept_bounds a b radius delta
  let best: Maybe Hit = #Nothing
  let best_time = 2.0
  for index in spatial.query scene.index low high:
    let proxy = scene.proxies[index]
    if accepts filter proxy && touches_bounds proxy low high:
      if let #Some (t, point, normal, surface, depth) = cast_shape proxy.shape a b radius delta:
        if t < best_time:
          best_time := t
          best := #Some (#Hit { id: proxy.id, proxy: index, time: t, distance: t * delta.length, point, normal, surface, depth })
  return best

const solid_filter = fn (mask: U32) => #Filter { mask, skip: 0, triggers: #False, walkers: #True, dynamics: #True }

// A ray: the nearest hit within `reach` along `direction`, never entity `skip`.
const ray = fn (scene: Scene) => fn (origin: Vec3) => fn (direction: Vec3) => fn (reach: F32) => fn (mask: U32) => fn (skip: U32) => do:
  // Vec3.normalized, then scaled by the reach.
  let length = sqrt (direction.x * direction.x + direction.y * direction.y + direction.z * direction.z)
  let delta = if length == 0.0 then #Vec3 { x: direction.x * reach, y: direction.y * reach, z: direction.z * reach } else #Vec3 { x: direction.x / length * reach, y: direction.y / length * reach, z: direction.z / length * reach }
  return cast scene origin origin 0.0 delta (#Filter { mask, skip, triggers: #False, walkers: #True, dynamics: #True })

// Every proxy overlapping a sphere, by ascending source index.
const overlap_sphere = fn (scene: Scene) => fn (center: Vec3) => fn (radius: F32) => fn (mask: U32) => do:
  let low = #Vec3 { x: center.x - radius, y: center.y - radius, z: center.z - radius }
  let high = #Vec3 { x: center.x + radius, y: center.y + radius, z: center.z + radius }
  let found: List U32 = []
  for index in spatial.query scene.index low high:
    let proxy = scene.proxies[index]
    if (proxy.layer & mask) != 0 && touches_bounds proxy low high:
      let gap = shapes.segment_gap proxy.shape center center
      if gap.dist <= radius:
        found := [...self, proxy.id]
  return Array.from_list found

// Every proxy overlapping a capsule.
const overlap_capsule = fn (scene: Scene) => fn (a: Vec3) => fn (b: Vec3) => fn (radius: F32) => fn (mask: U32) => do:
  let (low, high) = swept_bounds a b radius shapes.zero
  let found: List U32 = []
  for index in spatial.query scene.index low high:
    let proxy = scene.proxies[index]
    if (proxy.layer & mask) != 0 && touches_bounds proxy low high:
      let gap = shapes.segment_gap proxy.shape a b
      if gap.dist <= radius:
        found := [...self, proxy.id]
  return Array.from_list found

// Is the point inside any solid (non-trigger) proxy?
const point_solid = fn (scene: Scene) => fn (p: Vec3) => fn (mask: U32) => do:
  for index in spatial.query scene.index p p:
    let proxy = scene.proxies[index]
    if (proxy.layer & mask) != 0 && Bool.not proxy.trigger && touches_bounds proxy p p:
      let gap = shapes.segment_gap proxy.shape p p
      if gap.dist <= 0.0:
        return #True
  return #False

// Share the caller's invalidation batch with other derived views. Sources remain authoritative.
const update_changes = fn sources => fn previous => fn (change: changes.Changes) =>
  if change.reset then build sources else update sources previous (changes.affected change)

// Immutable query values compose independent spatial indexes without rebuilding
// their geometry. Parts retain declaration order, including equal-time ties.
type Queries is data = #Queries { parts: Array Scene }
const queries = fn sc => #Queries { parts: #[sc] }
const together = fn (a: Queries) => fn (b: Queries) => #Queries { parts: @array.concat a.parts b.parts }
const query_cast = fn (queries: Queries) => fn a => fn b => fn radius => fn delta => fn filter => do:
  let best: Maybe Hit = #Nothing
  let best_time = 2.0
  let offset = 0
  for part in queries.parts:
    if let #Some hit = cast part a b radius delta filter:
      if hit.time < best_time:
        best_time := hit.time
        best := #Some (#Hit { id: hit.id, proxy: offset + hit.proxy, time: hit.time, distance: hit.distance,
          point: hit.point, normal: hit.normal, surface: hit.surface, depth: hit.depth })
    offset := self + part.proxies.length
  return best
const query_overlap_sphere = fn (queries: Queries) => fn center => fn radius => fn mask =>
  array.flatten (array.map (fn part => overlap_sphere part center radius mask) queries.parts)
const query_overlap_capsule = fn (queries: Queries) => fn a => fn b => fn radius => fn mask =>
  array.flatten (array.map (fn part => overlap_capsule part a b radius mask) queries.parts)
const query_point_solid = fn (queries: Queries) => fn point => fn mask => do:
  for part in queries.parts:
    if point_solid part point mask:
      return #True
  return #False
const query_ray = fn (queries: Queries) => fn origin => fn direction => fn reach => fn mask => fn skip => do:
  let best: Maybe Hit = #Nothing
  let best_time = 2.0
  let offset = 0
  for part in queries.parts:
    if let #Some hit = ray part origin direction reach mask skip:
      if hit.time < best_time:
        best_time := hit.time
        best := #Some (#Hit { id: hit.id, proxy: offset + hit.proxy, time: hit.time, distance: hit.distance,
          point: hit.point, normal: hit.normal, surface: hit.surface, depth: hit.depth })
    offset := self + part.proxies.length
  return best

sources.lib/physics.blot:
import * as graph from "./graph"
import * as joints from "./joints"
import * as array from "std/array"
import { Vec3 } from "std/vector"
import { Quat } from "./math"
import * as math from "./math"
import * as shapes from "./shapes"
import * as contact from "./contact"
import * as scene from "./scene"
import * as rigid from "./rigid"
import * as character from "./character"
import * as sort from "./sort"
import { Proxy, Rigid, Scene, Source, Walker } from "./scene"

// Characters move first; rigid solving updates the caller-owned contact cache.
// Source order and ascending U32 contact ids keep simulation deterministic.

type Config is data = #Config {
  gravity: Vec3,
  substeps: U32,
  sleep_time: F32,
  linear_sleep: F32,
  angular_sleep: F32,
}

// What a step changed on one source.
type Result is data = #Result {
  source: U32,
  position: Vec3,
  rotation: Quat,
  rigid: Maybe Rigid,
  walker: Maybe Walker,
}

// Caller-owned warm-start state. Entity ids remain U32 throughout simulation.
type CachedContact is data = #CachedContact {
  a: U32,
  b: U32,
  point: Vec3,
  normal: Vec3,
  normal_impulse: F32,
  tangent_impulse: Vec3,
}
type Cache is data = #Cache { contacts: Array CachedContact }
const empty_cache = #Cache { contacts: #[] }
const default_config = #Config {
  gravity: math.vec3 0.0 (-9.81) 0.0,
  substeps: 4,
  sleep_time: 0.5,
  linear_sleep: 0.05,
  angular_sleep: 0.05,
}

const no_slot = 0.0 - 1.0

const rigid_of = fn (source: Source) => case source.rigid of
  #Some r => r
  #Nothing => #scene.Rigid {
    kind: #scene.Static,
    mass: 1.0,
    gravity_scale: 1.0,
    linear_damping: 0.0,
    angular_damping: 0.0,
    can_sleep: #True,
    continuous: #False,
    linear_velocity: math.zero3,
    angular_velocity: math.zero3,
    sleeping: #False,
    sleep_time: 0.0,
  }

// The velocity a proxy moves with this step.
const velocity_of = fn (sources: Array Source) => fn (proxy: Proxy) => do:
  let source = sources[proxy.source]
  if proxy.walker:
    let #Some w = source.walker else:
      return math.zero3
    return w.velocity
  return (rigid_of source).linear_velocity

const is_mover = fn (proxy: Proxy) => proxy.kind >= scene.kind_kinematic && Bool.not proxy.trigger

// Which proxies are movers: kinematic and dynamic bodies, in order.
const mover_ids = fn (proxies: Array Proxy) => do:
  let found = @array.fill proxies.length 0
  let count = 0
  for i in 0..proxies.length:
    if is_mover proxies[i]:
      found[count] := i
      count := self + 1
  return @array.generate count (fn (k: U32) => found[k])

// Broad phase ------------------------------------------------------------------------

const layers_meet = fn (a: Proxy) => fn (b: Proxy) =>
  (a.layer & b.mask) != 0 && (b.layer & a.mask) != 0

// The component of v along axis 0, 1 or 2.
// Sweep active movers along their widest axis; binary-search static bounds.
const broad_phase = fn (proxies: Array Proxy) => fn (movers: Array U32) => fn (grow: Array F32) => fn (active: Array F32) => do:
  let m = movers.length
  let lo = @array.fill (m * 3) 0.0
  let hi = @array.fill (m * 3) 0.0
  let mine: List U32 = []
  for k in 0..m:
    if active[movers[k]] > 0.0:
      mine := [...self, k]
      let p = proxies[movers[k]]
      let g = grow[k]
      lo[k * 3] := p.low.x - g
      lo[k * 3 + 1] := p.low.y - g
      lo[k * 3 + 2] := p.low.z - g
      hi[k * 3] := p.high.x + g
      hi[k * 3 + 1] := p.high.y + g
      hi[k * 3 + 2] := p.high.z + g
  let live = Array.from_list mine
  let n = live.length
  let found: List U32 = []
  if n == 0:
    return #[]
  // Sweep along the axis where the active movers spread most.
  let mx = 0.0
  let my = 0.0
  let mz = 0.0
  for t in 0..n:
    let k = live[t]
    mx := self + lo[k * 3] + hi[k * 3]
    my := self + lo[k * 3 + 1] + hi[k * 3 + 1]
    mz := self + lo[k * 3 + 2] + hi[k * 3 + 2]
  let inv = 0.5 / U32.to_f32 n
  let vx = 0.0
  let vy = 0.0
  let vz = 0.0
  for t in 0..n:
    let k = live[t]
    let dx = (lo[k * 3] + hi[k * 3]) * 0.5 - mx * inv
    let dy = (lo[k * 3 + 1] + hi[k * 3 + 1]) * 0.5 - my * inv
    let dz = (lo[k * 3 + 2] + hi[k * 3 + 2]) * 0.5 - mz * inv
    vx := self + dx * dx
    vy := self + dy * dy
    vz := self + dz * dz
  let axis = 2
  if vy >= vz:
    axis := 1
  if vx >= vy && vx >= vz:
    axis := 0
  let keys = @array.generate n (fn (t: U32) => lo[live[t] * 3 + axis])
  let order = sort.order keys
  // Find each sweep interval's end before collecting pairs. Early loop exits
  // make the compiler copy the growing list on every append.
  for oi in 0..n:
    let i = live[order[oi]]
    let reach = hi[i * 3 + axis]
    let first = oi + 1
    let last = n
    for 0..32:
      if first < last:
        let mid = (first + last) / 2
        if lo[live[order[mid]] * 3 + axis] <= reach:
          first := mid + 1
        else:
          last := mid
    for oj in (oi + 1)..first:
      let j = live[order[oj]]
      if lo[i * 3] <= hi[j * 3] && hi[i * 3] >= lo[j * 3] && lo[i * 3 + 1] <= hi[j * 3 + 1] && hi[i * 3 + 1] >= lo[j * 3 + 1] && lo[i * 3 + 2] <= hi[j * 3 + 2] && hi[i * 3 + 2] >= lo[j * 3 + 2]:
        let pi = proxies[movers[i]]
        let pj = proxies[movers[j]]
        if (pi.kind == scene.kind_dynamic || pj.kind == scene.kind_dynamic) && layers_meet pi pj:
          let first = movers[i]
          let second = movers[j]
          found := [...self, first]
          found := [...self, second]
  // Active movers against everything at rest.
  let rest: List U32 = []
  for s in 0..proxies.length:
    if active[s] == 0.0 && Bool.not proxies[s].trigger:
      rest := [...self, s]
  let rest_ids = Array.from_list rest
  let nr = rest_ids.length
  if nr > 0:
    let order_r = sort.order (@array.generate nr (fn (t: U32) => proxies[rest_ids[t]].low.x))
    let sorted = @array.generate nr (fn (t: U32) => rest_ids[order_r[t]])
    let low_x = @array.generate nr (fn (t: U32) => proxies[sorted[t]].low.x)
    let reach_x = @array.fill nr 0.0
    let running = (-1000000000.0)
    for t in 0..nr:
      running := max self proxies[sorted[t]].high.x
      reach_x[t] := running
    for t in 0..n:
      let k = live[t]
      let pm = proxies[movers[k]]
      // First resting proxy whose running maximum reaches the mover, and the
      // first whose low x is beyond it.
      let first = 0
      let last = nr
      for 0..32:
        if first < last:
          let mid = (first + last) / 2
          if reach_x[mid] < lo[k * 3]:
            first := mid + 1
          else:
            last := mid
      let begin = first
      first := 0
      last := nr
      for 0..32:
        if first < last:
          let mid = (first + last) / 2
          if low_x[mid] <= hi[k * 3]:
            first := mid + 1
          else:
            last := mid
      for u in begin..first:
        let ps = proxies[sorted[u]]
        if (pm.kind == scene.kind_dynamic || ps.kind == scene.kind_dynamic) && layers_meet pm ps && overlap_bounds lo hi k ps:
          let first_proxy = movers[k]
          let second_proxy = sorted[u]
          found := [...self, first_proxy]
          found := [...self, second_proxy]
  return Array.from_list found

const overlap_bounds = fn (lo: Array F32) => fn (hi: Array F32) => fn (k: U32) => fn (p: Proxy) =>
  lo[k * 3] <= p.high.x && hi[k * 3] >= p.low.x && lo[k * 3 + 1] <= p.high.y && hi[k * 3 + 1] >= p.low.y && lo[k * 3 + 2] <= p.high.z && hi[k * 3 + 2] >= p.low.z

// The pairs sorted by the smaller entity id, then the larger, and each pair
// ordered the same way. Input and output are flat proxy index lists.
const canonical_pairs = fn (proxies: Array Proxy) => fn (rank: Array U32) => fn (pairs: Array U32) => do:
  let count = pairs.length / 2
  let np = proxies.length
  let first = @array.generate count (fn (p: U32) => do:
    let a = pairs[p * 2]
    let b = pairs[p * 2 + 1]
    if rank[a] < rank[b]:
      return a
    return b)
  let second = @array.generate count (fn (p: U32) => do:
    let a = pairs[p * 2]
    let b = pairs[p * 2 + 1]
    if rank[a] < rank[b]:
      return b
    return a)
  if np <= 65535:
    let order = sort.order_u32 (@array.generate count (fn (p: U32) => rank[first[p]] * np + rank[second[p]]))
    return @array.generate (count * 2) (fn (k: U32) => do:
      let p = order[k / 2]
      if k % 2 == 0:
        return first[p]
      return second[p])
  let by_second = sort.order_u32 (@array.generate count (fn (p: U32) => proxies[second[p]].id))
  let by_first = sort.order_u32 (@array.generate count (fn (p: U32) => proxies[first[by_second[p]]].id))
  return @array.generate (count * 2) (fn (k: U32) => do:
    let p = by_second[by_first[k / 2]]
    if k % 2 == 0:
      return first[p]
    return second[p])

// Index of the first cache row for the pair (a, b), or the length if absent.
const cache_find = fn (cache: Cache) => fn (a: U32) => fn (b: U32) => do:
  let low = 0
  let high = cache.contacts.length
  for 0..32:
    if low >= high:
      break
    let mid = (low + high) / 2
    let c = cache.contacts[mid]
    if c.a < a || (c.a == a && c.b < b):
      low := mid + 1
    else:
      high := mid
  return low

// Reuse the nearest cached impulse for this exact entity pair: the normal
// impulse and the tangential impulse's x, y and z.
const cache_match = fn (cache: Cache) => fn (a: U32) => fn (b: U32) => fn (px: F32) => fn (py: F32) => fn (pz: F32) => do:
  let rows = cache.contacts.length
  let i = cache_find cache a b
  let best = 0.0225
  let jn = 0.0
  let jtx = 0.0
  let jty = 0.0
  let jtz = 0.0
  for 0..rows:
    if i >= rows:
      break
    let c = cache.contacts[i]
    if c.a != a || c.b != b:
      break
    let dx = c.point.x - px
    let dy = c.point.y - py
    let dz = c.point.z - pz
    let d = dx * dx + dy * dy + dz * dz
    if d < best:
      best := d
      jn := c.normal_impulse
      jtx := c.tangent_impulse.x
      jty := c.tangent_impulse.y
      jtz := c.tangent_impulse.z
    i := self + 1
  return (jn, jtx, jty, jtz)

const proxy_with_id = fn (proxies: Array Proxy) => fn (by_id: Array U32) => fn (id: U32) => do:
  let low = 0
  let high = by_id.length
  for 0..32:
    if low >= high:
      break
    let mid = (low + high) / 2
    if proxies[by_id[mid]].id < id:
      low := mid + 1
    else:
      high := mid
  if low < by_id.length && proxies[by_id[low]].id == id:
    return by_id[low]
  return proxies.length


// The first proxy with entity id `id`, or the proxy count, by binary search
// of `ids` (each proxy's id) in the stable ascending order `by_id`.
const index_of_id = fn (ids: Array U32) => fn (by_id: Array U32) => fn (id: U32) => do:
  let low = 0
  let high = by_id.length
  for 0..32:
    if low < high:
      let mid = (low + high) / 2
      if ids[by_id[mid]] < id:
        low := mid + 1
      else:
        high := mid
  if low < by_id.length && ids[by_id[low]] == id:
    return by_id[low]
  return ids.length

// Solver -----------------------------------------------------------------------------

type Island is data = #Island { parent: Array U32 }

const root_of = fn (parent: Array U32) => fn (i: U32) => do:
  let r = i
  for 0..parent.length:
    let p = parent[r]
    if p == r:
      break
    r := p
  return r

// Advance the rigid bodies by dt. `scene` holds the proxies; `sources` the
// matching entity data. Returns results for the bodies that moved and the new
// contact cache.
const contact_substeps = fn (substeps: U32) => fn (row_array: Array F32) => fn (inv_mass: Array F32) => fn (pos: Array F32) => do:
  // Height-ordered support chains need stiffer contacts above twelve bodies.
  let total = row_array.length / rigid.stride
  let m = inv_mass.length
  let under = @array.fill total 0
  let over = @array.fill total 0
  let heights = @array.fill total 0.0
  let supports = 0
  for c in 0..total:
    let o = c * rigid.stride
    let a = row_array[o]
    let b = row_array[o + 1]
    if a >= 0.0 && b >= 0.0:
      let ka = F32.to_u32 a
      let kb = F32.to_u32 b
      if inv_mass[ka] > 0.0 && inv_mass[kb] > 0.0:
        let ny = row_array[o + 3]
        if ny > 0.7:
          under[supports] := ka
          over[supports] := kb
          heights[supports] := pos[ka * 3 + 1]
          supports := self + 1
        if ny < (-0.7):
          under[supports] := kb
          over[supports] := ka
          heights[supports] := pos[kb * 3 + 1]
          supports := self + 1
  let depth = @array.fill m 1
  let deepest = 1
  if supports >= 11:
    let by_height = sort.order (@array.generate supports (fn (i: U32) => heights[i]))
    for r in 0..supports:
      let row = by_height[r]
      let reached = depth[under[row]] + 1
      if reached > depth[over[row]]:
        depth[over[row]] := reached
        deepest := max self reached
  if deepest >= 30:
    return min 16 (substeps * 4)
  if deepest >= 12:
    return min 16 (substeps * 2)
  return substeps

const prepare_joints = fn (joint_list: Array joints.Joint) => fn (sources: Array Source) => fn (sc: Scene) => fn (slot_of: Array F32) => do:
  let prepared: List joints.Link = []
  for joint in joint_list:
    if joint.a < sources.length && joint.b < sources.length && joints.valid joint:
      let a = sources[joint.a]
      let b = sources[joint.b]
      let slot_a = no_slot
      let slot_b = no_slot
      let proxy_a = sc.slots[joint.a]
      let proxy_b = sc.slots[joint.b]
      if proxy_a < slot_of.length:
        slot_a := slot_of[proxy_a]
      if proxy_b < slot_of.length:
        slot_b := slot_of[proxy_b]
      let body_a = rigid_of a
      let body_b = rigid_of b
      prepared := [...self, #joints.Link { joint, a: slot_a, b: slot_b, position_a: a.position, position_b: b.position, rotation_a: a.rotation, rotation_b: b.rotation, velocity_a: body_a.linear_velocity, velocity_b: body_b.linear_velocity, angular_a: body_a.angular_velocity, angular_b: body_b.angular_velocity }]
  return Array.from_list prepared

const sleep_islands = fn (config: Config) => fn (dt: F32) => fn (sources: Array Source) => fn (proxies: Array Proxy) => fn (movers: Array U32) => fn (connected: Array U32) => fn (inv_mass: Array F32) => fn (row_array: Array F32) => fn (new_vel: Array F32) => do:
  // Sleeping: islands of touching awake bodies sleep together once all of
  // them have been still for long enough.
  let m = movers.length
  let count = row_array.length / rigid.stride
  let parent = @array.generate m (fn (k: U32) => k)
  let sizes = @array.fill m 1
  for c in 0..count:
    let o = c * rigid.stride
    let a = row_array[o]
    let b = row_array[o + 1]
    if a >= 0.0 && b >= 0.0:
      let ka = F32.to_u32 a
      let kb = F32.to_u32 b
      if inv_mass[ka] > 0.0 && inv_mass[kb] > 0.0:
        // Find both roots inline: handing `parent` to a function would make
        // the union's writes below copy it.
        let ra = ka
        for 0..m:
          let up = parent[ra]
          if up == ra:
            break
          ra := up
        let rb = kb
        for 0..m:
          let up = parent[rb]
          if up == rb:
            break
          rb := up
        if ra != rb:
          // Size weighting bounds root walks even for dense canonical pairs.
          let size_a = sizes[ra]
          let size_b = sizes[rb]
          let smaller = ra
          let larger = rb
          if size_a > size_b || (size_a == size_b && ra < rb):
            smaller := rb
            larger := ra
          parent[smaller] := larger
          sizes[larger] := size_a + size_b
  let still = @array.fill m 0.0
  let island_time = @array.fill m 1000000.0
  for k in 0..m:
    if inv_mass[k] > 0.0:
      let proxy = proxies[movers[k]]
      let body = rigid_of sources[proxy.source]
      let v = k * 6
      let lin = sqrt (new_vel[v] * new_vel[v] + new_vel[v + 1] * new_vel[v + 1] + new_vel[v + 2] * new_vel[v + 2])
      let ang = sqrt (new_vel[v + 3] * new_vel[v + 3] + new_vel[v + 4] * new_vel[v + 4] + new_vel[v + 5] * new_vel[v + 5])
      let quiet = lin < config.linear_sleep && (ang < config.angular_sleep || ang * proxy.inscribed < config.linear_sleep) && body.can_sleep && connected[proxy.source] == 0
      let time = 0.0
      if quiet:
        time := body.sleep_time + dt
      still[k] := time
      let root = root_of parent k
      island_time[root] := min island_time[root] time
  return (parent, still, island_time)

const prepare_bodies = fn (sources: Array Source) => fn (proxies: Array Proxy) => fn (movers: Array U32) => fn (origins: Array Vec3) => fn (velocities: Array Vec3) => fn (woke: Array F32) => do:
  let np = proxies.length
  let m = movers.length
  let slot_of = @array.fill np no_slot
  for k in 0..m:
    slot_of[movers[k]] := U32.to_f32 k
  let pos = @array.fill (m * 3) 0.0
  let rot = @array.fill (m * 4) 0.0
  let vel = @array.fill (m * 6) 0.0
  let inv_mass = @array.fill m 0.0
  let inv_inertia = @array.fill (m * 3) 0.0
  let gravity_scale = @array.fill m 0.0
  let linear_damping = @array.fill m 0.0
  let angular_damping = @array.fill m 0.0
  for k in 0..m:
    let proxy = proxies[movers[k]]
    let source = sources[proxy.source]
    let body = rigid_of source
    pos[k * 3] := origins[movers[k]].x
    pos[k * 3 + 1] := origins[movers[k]].y
    pos[k * 3 + 2] := origins[movers[k]].z
    rot[k * 4] := source.rotation.x
    rot[k * 4 + 1] := source.rotation.y
    rot[k * 4 + 2] := source.rotation.z
    rot[k * 4 + 3] := source.rotation.w
    let v = velocities[movers[k]]
    vel[k * 6] := v.x
    vel[k * 6 + 1] := v.y
    vel[k * 6 + 2] := v.z
    vel[k * 6 + 3] := body.angular_velocity.x
    vel[k * 6 + 4] := body.angular_velocity.y
    vel[k * 6 + 5] := body.angular_velocity.z
    if proxy.kind == scene.kind_dynamic && woke[movers[k]] > 0.0:
      let mass = max 0.0001 body.mass
      inv_mass[k] := 1.0 / mass
      inv_inertia[k * 3] := 1.0 / (mass * max 0.00001 proxy.inertia.x)
      inv_inertia[k * 3 + 1] := 1.0 / (mass * max 0.00001 proxy.inertia.y)
      inv_inertia[k * 3 + 2] := 1.0 / (mass * max 0.00001 proxy.inertia.z)
      gravity_scale[k] := body.gravity_scale
      linear_damping[k] := body.linear_damping
      angular_damping[k] := body.angular_damping
  let bodies = #rigid.Bodies { pos, rot, vel, inv_mass, inv_inertia, gravity_scale, linear_damping, angular_damping }
  return (bodies, slot_of)

const prepare_contacts = fn (dt: F32) => fn (proxies: Array Proxy) => fn (velocities: Array Vec3) => fn (woke: Array F32) => fn (by_id: Array U32) => fn (candidates: Array U32) => fn (bodies: rigid.Bodies) => fn (slot_of: Array F32) => fn (cache: Cache) => do:
  let np = proxies.length
  let rank = @array.fill np 0
  for t in 0..np:
    rank[by_id[t]] := t
  let pairs = canonical_pairs proxies rank candidates
  let iw0 = rigid.inertia_table bodies.rot bodies.inv_inertia
  // Find every pair's contacts first, so the row tables are allocated at
  // their exact size.
  let pair_count = pairs.length / 2
  // How far each pair closes during the step.
  let closing = @array.generate pair_count (fn (p: U32) => do:
    let va = velocities[pairs[p * 2]]
    let vb = velocities[pairs[p * 2 + 1]]
    let dx = va.x - vb.x
    let dy = va.y - vb.y
    let dz = va.z - vb.z
    return sqrt (dx * dx + dy * dy + dz * dz) * dt)
  let found = @array.generate pair_count (fn (p: U32) => do:
    let ia = pairs[p * 2]
    let ib = pairs[p * 2 + 1]
    if woke[ia] > 0.0 || woke[ib] > 0.0:
      return contact.between proxies[ia].shape proxies[ib].shape (0.02 + closing[p])
    return #[])
  // Omit contacts that cannot close during this step.
  let reach = @array.generate pair_count (fn (p: U32) => 0.008 + closing[p])
  let used = 0
  for p in 0..pair_count:
    let limit = reach[p]
    for c in found[p]:
      if c.sep <= limit:
        used := self + 1
  let row_buf = @array.fill (used * rigid.stride) 0.0
  let imp_buf = @array.fill (used * rigid.impulse_stride) 0.0
  let row_a_ids = @array.fill used 0
  let row_b_ids = @array.fill used 0
  let r = 0
  for p in 0..pair_count:
    let ia = pairs[p * 2]
    let ib = pairs[p * 2 + 1]
    let pa = proxies[ia]
    let pb = proxies[ib]
    let a = slot_of[ia]
    let b = slot_of[ib]
    let friction = sqrt (pa.friction * pb.friction)
    let restitution = max pa.restitution pb.restitution
    let limit = reach[p]
    for c in found[p]:
      if c.sep <= limit:
        let point = c.point
        let normal = c.normal
        let row = rigid.prepare_row_xyz bodies iw0 a b normal.x normal.y normal.z point.x point.y point.z c.sep friction restitution
        let (jn, jtx, jty, jtz) = cache_match cache pa.id pb.id point.x point.y point.z
        let ro = r * rigid.stride
        for k in 0..rigid.stride:
          row_buf[ro + k] := row[k]
        row_a_ids[r] := pa.id
        row_b_ids[r] := pb.id
        let io = r * rigid.impulse_stride
        imp_buf[io] := jn
        imp_buf[io + 1] := jtx * row[17] + jty * row[18] + jtz * row[19]
        imp_buf[io + 2] := jtx * row[20] + jty * row[21] + jtz * row[22]
        r := self + 1
  return (row_buf, imp_buf, row_a_ids, row_b_ids)

// Results for the woken dynamic bodies, in mover order, gathered by index
// into an exactly sized array: appending records to a List one at a time
// costs more with every append.
const moved_results = fn (config: Config) => fn (sources: Array Source) => fn (proxies: Array Proxy) => fn (movers: Array U32) => fn (woke: Array F32) => fn (parent: Array U32) => fn (island_time: Array F32) => fn (still: Array F32) => fn (new_pos: Array F32) => fn (new_rot: Array F32) => fn (new_vel: Array F32) => do:
  let m = movers.length
  let slots = @array.fill m 0
  let count = 0
  for k in 0..m:
    let idx = movers[k]
    if proxies[idx].kind == scene.kind_dynamic && woke[idx] > 0.0:
      slots[count] := k
      count := self + 1
  return @array.generate count (fn (r: U32) => do:
    let k = slots[r]
    let proxy = proxies[movers[k]]
    let body = rigid_of sources[proxy.source]
    let root = root_of parent k
    let sleep_now = island_time[root] >= config.sleep_time
    let v = k * 6
    let lin = if sleep_now then math.zero3 else #Vec3 { x: new_vel[v], y: new_vel[v + 1], z: new_vel[v + 2] }
    let ang = if sleep_now then math.zero3 else #Vec3 { x: new_vel[v + 3], y: new_vel[v + 4], z: new_vel[v + 5] }
    let updated = #scene.Rigid {
      kind: body.kind, mass: body.mass, gravity_scale: body.gravity_scale,
      linear_damping: body.linear_damping, angular_damping: body.angular_damping,
      can_sleep: body.can_sleep, continuous: body.continuous,
      linear_velocity: lin, angular_velocity: ang,
      sleeping: sleep_now, sleep_time: still[k],
    }
    return #Result {
      source: proxy.source,
      position: rigid.vec new_pos (k * 3),
      rotation: rigid.quat new_rot (k * 4),
      rigid: #Some updated,
      walker: #Nothing,
    })

const simulate_queries = fn (queries: scene.Queries) => fn (joint_list: Array joints.Joint) => fn (config: Config) => fn (dt: F32) => fn (sources: Array Source) => fn (sc: Scene) => fn (cache: Cache) => do:
  if Bool.not (dt > 0.0 && dt - dt == 0.0):
    return (#[], cache)
  let np = sc.proxies.length
  // One loop fills the per-proxy arrays together; the walker and sweep loops
  // below write them in place.
  let proxies = @array.generate np (fn (i: U32) => sc.proxies[i])
  // Explicit joints wake their connected dynamics.
  let connected = @array.fill sources.length 0
  for joint in joint_list:
    if joints.valid joint && joint.a < sources.length && joint.b < sources.length:
      connected[joint.a] := 1
      connected[joint.b] := 1
  let origins = @array.fill np math.zero3
  let velocities = @array.fill np math.zero3
  let angulars = @array.fill np math.zero3
  // Awake flags per proxy: 1 for dynamic bodies that are not asleep.
  let awake = @array.fill np 0.0
  for i in 0..np:
    let p = proxies[i]
    origins[i] := sources[p.source].position
    if p.kind >= scene.kind_kinematic:
      velocities[i] := velocity_of sources p
      if Bool.not p.walker:
        angulars[i] := (rigid_of sources[p.source]).angular_velocity
    if p.kind == scene.kind_dynamic && Bool.not p.trigger:
      if connected[p.source] > 0 || Bool.not (rigid_of sources[p.source]).sleeping:
        awake[i] := 1.0
  // Proxy ids in stable ascending order; moving proxies keeps their ids.
  let ids = @array.generate np (fn (i: U32) => sc.proxies[i].id)
  let by_id = sort.order_u32 ids
  // Characters move first, on the world as it stood; they shove dynamic
  // bodies they walk into and leave their motion as a velocity for the solver.
  // The loop writes the per-proxy arrays in place, so it hands them to no
  // function, and it records each walker's outcome for an exact result array.
  let walked = @array.fill np 0
  let walked_at = @array.fill np math.zero3
  let walked_state = @array.fill np scene.default_walker
  let wake_by_push = @array.fill np 0.0
  for i in 0..np:
    let proxy = proxies[i]
    if proxy.walker && Bool.not proxy.trigger:
      let source = sources[proxy.source]
      if let #Some walker = source.walker:
        if let #shapes.Capsule { a, b, radius } = proxy.shape:
          let body = #character.Body { low: a - source.position, high: b - source.position, radius }
          let filter = #scene.Filter { mask: proxy.mask, skip: proxy.id, triggers: #False, walkers: #False, dynamics: #True }
          let under = if walker.ground == 0 then np else index_of_id ids by_id walker.ground
          // How far the platform underfoot moved this step: its translation
          // plus the turn about its own origin, at the character's feet.
          let carry = math.zero3
          if walker.grounded && under < np:
            let platform = proxies[under]
            if platform.kind != scene.kind_static:
              let origin = sources[platform.source].position
              carry := (velocities[under] + angulars[under].cross (source.position - origin)) * dt
          let moved = character.move_queries queries body filter source.position walker carry dt
          let shift = moved.position - source.position
          proxies[i] := scene.shifted proxy shift
          origins[i] := moved.position
          velocities[i] := shift / dt
          for h in moved.hits:
            if h.proxy < np:
              let other = proxies[h.proxy]
              if other.kind == scene.kind_dynamic && Bool.not other.trigger:
                let away = shapes.neg h.normal
                let approach = max 0.0 (away.dot walker.velocity)
                let current = velocities[h.proxy].dot away
                let extra = max 0.0 (approach * walker.push - current)
                velocities[h.proxy] := velocities[h.proxy] + away * extra
                if extra > 0.0:
                  wake_by_push[h.proxy] := 1.0
          walked[i] := 1
          walked_at[i] := moved.position
          walked_state[i] := moved.walker
  // Sweep each fast body's inscribed sphere against immovable colliders.
  for i in 0..np:
    let proxy = proxies[i]
    if proxy.kind == scene.kind_dynamic && awake[i] > 0.0 && Bool.not proxy.trigger:
      let body = rigid_of sources[proxy.source]
      let delta = velocities[i] * dt
      let travel = delta.length
      if body.continuous && travel > proxy.inscribed * 0.5 && travel > 0.0001:
        let filter = #scene.Filter { mask: proxy.mask, skip: proxy.id, triggers: #False, walkers: #False, dynamics: #False }
        if let #Some h = scene.query_cast queries origins[i] origins[i] proxy.inscribed delta filter:
          if h.depth == 0.0:
            let shift = delta * max 0.0 (h.time - 0.01 / travel)
            proxies[i] := scene.shifted proxy shift
            origins[i] := origins[i] + shift
  let movers = mover_ids proxies
  let m = movers.length
  let grow = @array.generate m (fn (k: U32) => 0.04 + (velocities[movers[k]]).length * dt)
  // Active: awake or pushed dynamic bodies, moving kinematic bodies.
  let woke = @array.generate np (fn (i: U32) => max awake[i] wake_by_push[i])
  let active0 = @array.fill np 0.0
  for i in 0..np:
    if woke[i] > 0.0 || (proxies[i].kind == scene.kind_kinematic && Bool.not proxies[i].trigger && velocities[i].length_squared > 0.0000001):
      active0[i] := 1.0
  let candidates0 = broad_phase proxies movers grow active0
  // Active contacts wake sleepers and propagate through cached support pairs.
  let pair_count = candidates0.length / 2
  let woken = #False
  for p in 0..pair_count:
    let a = candidates0[p * 2]
    let b = candidates0[p * 2 + 1]
    if proxies[a].kind == scene.kind_dynamic && woke[a] == 0.0 && active0[b] > 0.0:
      woke[a] := 1.0
      woken := #True
    if proxies[b].kind == scene.kind_dynamic && woke[b] == 0.0 && active0[a] > 0.0:
      woke[b] := 1.0
      woken := #True
  let cache_rows = cache.contacts.length
  let row_a = @array.generate cache_rows (fn (r: U32) => proxy_with_id proxies by_id cache.contacts[r].a)
  let row_b = @array.generate cache_rows (fn (r: U32) => proxy_with_id proxies by_id cache.contacts[r].b)
  if woken:
    if cache_rows > 0x7FFFFFFF:
      return @panic "contact wake edge count overflows"
    let endpoints = @array.fill (cache_rows * 2) 0
    let targets = @array.fill (cache_rows * 2) 0
    let used = 0
    for r in 0 .. cache_rows:
      let a = row_a[r]
      let b = row_b[r]
      if a < np && b < np:
        endpoints[used] := a
        targets[used] := b
        endpoints[used + 1] := b
        targets[used + 1] := a
        used := self + 2
    let #Some adjacency = graph.from_edges np (@array.slice endpoints 0 used) (@array.slice targets 0 used) else:
      return @panic "contact wake adjacency invariant"
    let roots = #[i | i <- @array.generate np (fn i => i), woke[i] > 0.0]
    let active = graph.reachable adjacency roots (@array.generate np (fn i => proxies[i].kind == scene.kind_dynamic))
    woke := @array.generate np (fn i => if active[i] then 1.0 else 0.0)
  // Bodies that just woke now need their contacts with everything near.
  let active1 = @array.generate np (fn (i: U32) => do:
    if woke[i] > 0.0 || active0[i] > 0.0:
      return 1.0
    return 0.0)
  let candidates = candidates0
  if woken:
    candidates := broad_phase proxies movers grow active1
  let (bodies, slot_of) = prepare_bodies sources proxies movers origins velocities woke
  let (row_array, imp_array, row_a_ids, row_b_ids) = prepare_contacts dt proxies velocities woke by_id candidates bodies slot_of cache
  let substeps = contact_substeps config.substeps row_array bodies.inv_mass bodies.pos
  let prepared = prepare_joints joint_list sources sc slot_of
  let (new_pos, new_rot, new_vel, solved) = rigid.solve_joints prepared dt substeps config.gravity bodies row_array imp_array
  let (parent, still, island_time) = sleep_islands config dt sources proxies movers connected bodies.inv_mass row_array new_vel
  let count = row_array.length / rigid.stride
  // Merge solved and unchanged sleeping contacts in exact U32 id order.
  let fresh = @array.generate count (fn (c: U32) => do:
    let o = c * rigid.stride
    let q = c * rigid.impulse_stride
    let jt1 = solved[q + 1]
    let jt2 = solved[q + 2]
    return #CachedContact {
      a: row_a_ids[c], b: row_b_ids[c],
      point: rigid.vec row_array (o + 24),
      normal: rigid.vec row_array (o + 2),
      normal_impulse: solved[q],
      tangent_impulse: #Vec3 {
        x: row_array[o + 17] * jt1 + row_array[o + 20] * jt2,
        y: row_array[o + 18] * jt1 + row_array[o + 21] * jt2,
        z: row_array[o + 19] * jt1 + row_array[o + 22] * jt2,
      },
    })
  let kept_rows = @array.fill cache_rows 0
  let kept = 0
  for r in 0..cache_rows:
    let ia = row_a[r]
    let ib = row_b[r]
    if ia < np && ib < np && woke[ia] == 0.0 && woke[ib] == 0.0:
      kept_rows[kept] := r
      kept := self + 1
  let carried = @array.generate kept (fn (r: U32) => cache.contacts[kept_rows[r]])
  let merged = merge_caches (#Cache { contacts: fresh }) (#Cache { contacts: carried })
  let bodies_moved = moved_results config sources proxies movers woke parent island_time still new_pos new_rot new_vel
  let walker_slots = @array.fill np 0
  let walkers = 0
  for i in 0..np:
    if walked[i] > 0:
      walker_slots[walkers] := i
      walkers := self + 1
  let walker_results = @array.generate walkers (fn (r: U32) => do:
    let i = walker_slots[r]
    let source = proxies[i].source
    return #Result { source, position: walked_at[i], rotation: sources[source].rotation, rigid: #Nothing, walker: #Some walked_state[i] })
  return (array.concat walker_results bodies_moved, merged)

const merge_caches = fn (a: Cache) => fn (b: Cache) => do:
  if b.contacts.is_empty:
    return a
  let na = a.contacts.length
  let nb = b.contacts.length
  // The merged order as indices: below na from a, from na on from b.
  let order = @array.fill (na + nb) 0
  let i = 0
  let j = 0
  for k in 0..(na + nb):
    let take_a = #False
    if j >= nb:
      take_a := #True
    else:
      if i < na:
        let ca = a.contacts[i]
        let cb = b.contacts[j]
        take_a := ca.a < cb.a || (ca.a == cb.a && ca.b <= cb.b)
    // One write a step: writes under both arms would copy the array.
    let at = na + j
    if take_a:
      at := i
      i := self + 1
    else:
      j := self + 1
    order[k] := at
  return #Cache { contacts: @array.generate (na + nb) (fn (k: U32) => do:
    let at = order[k]
    if at < na:
      return a.contacts[at]
    return b.contacts[at - na]) }

// Contact-only simulation retains its original API.
const simulate_joints = fn links => fn config => fn dt => fn sources => fn (sc: Scene) =>
  simulate_queries (scene.queries sc) links config dt sources sc

const simulate = fn (config: Config) => fn (dt: F32) => fn (sources: Array Source) => fn (sc: Scene) => fn (cache: Cache) => simulate_joints #[] config dt sources sc cache

// Apply a step to caller-owned sources. Kinematic poses remain caller supplied.
const apply = fn (sources: Array Source) => fn (results: Array Result) => do:
  let next = @array.generate sources.length (fn (i: U32) => sources[i])
  for r in results:
    let s = next[r.source]
    s.position := r.position
    s.rotation := r.rotation
    if let #Some rigid = r.rigid:
      s.rigid := #Some rigid
    if let #Some walker = r.walker:
      s.walker := #Some walker
    next[r.source] := s
  return next

// Convenience for small scenes; use scene.update + simulate to reuse geometry.
const step = fn (config: Config) => fn (dt: F32) => fn (sources: Array Source) => fn (cache: Cache) => do:
  let (results, next_cache) = simulate config dt sources (scene.build sources) cache
  return (apply sources results, next_cache)

// Joint simulation shares contact cache and integration with ordinary physics.
const step_joints = fn (joint_list: Array joints.Joint) => fn (config: Config) => fn (dt: F32) => fn (sources: Array Source) => fn (cache: Cache) => do:
  let (results, next_cache) = simulate_joints joint_list config dt sources (scene.build sources) cache
  return (apply sources results, next_cache)

// Queries take built scenes and layer masks; only overlaps include triggers.

const all_layers: U32 = 65535

// The first solid hit along a ray of length `reach`, ignoring the entity
// `skip` (0 for none): `physics.ray scene origin direction reach mask skip`.
const ray = fn (sc: Scene) => fn (origin: Vec3) => fn (direction: Vec3) => fn (reach: F32) => fn (mask: U32) => fn (skip: U32) => scene.ray sc origin direction reach mask skip

// Move a sphere by `delta`; the first thing it touches.
const sweep_sphere = fn (sc: Scene) => fn (center: Vec3) => fn (radius: F32) => fn (delta: Vec3) => fn (mask: U32) => fn (skip: U32) =>
  scene.cast sc center center radius delta (#scene.Filter { mask, skip, triggers: #False, walkers: #True, dynamics: #True })

// Move a capsule (the segment a-b with a radius) by `delta`.
const sweep_capsule = fn (sc: Scene) => fn (a: Vec3) => fn (b: Vec3) => fn (radius: F32) => fn (delta: Vec3) => fn (mask: U32) => fn (skip: U32) =>
  scene.cast sc a b radius delta (#scene.Filter { mask, skip, triggers: #False, walkers: #True, dynamics: #True })

// The entity ids overlapping a sphere or a capsule, triggers included.
const overlap_sphere = fn (sc: Scene) => fn (center: Vec3) => fn (radius: F32) => fn (mask: U32) => scene.overlap_sphere sc center radius mask
const overlap_capsule = fn (sc: Scene) => fn (a: Vec3) => fn (b: Vec3) => fn (radius: F32) => fn (mask: U32) => scene.overlap_capsule sc a b radius mask

// Is the point inside anything solid?
const point_solid = fn (sc: Scene) => fn (p: Vec3) => fn (mask: U32) => scene.point_solid sc p mask

// Did the last step have a contact between these two entities? `contacts` is
// the contact cache returned by `simulate`.
const touching = fn (cache: Cache) => fn (a: U32) => fn (b: U32) => do:
  let low = min a b
  let high = a
  if a < b:
    high := b
  let i = cache_find cache low high
  return i < cache.contacts.length && cache.contacts[i].a == low && cache.contacts[i].b == high

const contact_count = fn (cache: Cache) => cache.contacts.length

